const incoming = $input.first().json;
const topic = (incoming && incoming.query && incoming.query.topic) ? String(incoming.query.topic).trim() : 'AI agents for small businesses';
return [{ json: { topic } }];

const topic = $('Read Topic').first().json.topic;
const resp = $input.first().json;
const results = Array.isArray(resp.results) ? resp.results.slice(0, 8) : [];
let sourcesBlock = '';
results.forEach((r, i) => {
  const title = (r.title || 'Untitled').replace(/\s+/g, ' ').trim();
  const url = r.url || '';
  const content = (r.content || '').replace(/\s+/g, ' ').trim().slice(0, 400);
  sourcesBlock += `[${i + 1}] ${title}
URL: ${url}
Snippet: ${content}

`;
});
if (!sourcesBlock) sourcesBlock = 'No search results were returned. Note this explicitly and write from general knowledge while labeling it as Unknown/Inference.';

const system = `You are Mira, a research analyst. You are rigorous, neutral, and never speculate without labeling it. Work only from the provided search results / retrieved documents. For every factual claim include a [source: URL or doc title]. Explicitly separate Facts (in sources), Inference (your reasoning), and Unknown (not in sources — say so). State a confidence level (high/medium/low) for conclusions. Never invent a source or a statistic. Prefer recent sources and note publication dates. Output structured markdown: a 2-line summary, then findings as bullets, then a Sources list.`;

const task = `Write a structured markdown research brief on the topic: "${topic}".

Use ONLY the numbered search results below. Cite claims inline with bracketed numbers like [1], [2] that map to the Sources list.

Produce EXACTLY this structure:
# Research Brief: ${topic}
A two-line neutral overview of the topic.

## Key Points
- Bullet points of the most important findings, each with an inline [n] citation.

## Outlook
- 2-4 bullets on where this is heading, labeling Inference vs Fact.

## Sources
A numbered list [n] mapping each number to its title and URL.

SEARCH RESULTS:
${sourcesBlock}`;

const prompt = `${system}

${task}`;
return [{ json: { model: 'qwen3:8b', prompt, topic } }];

const md = String($input.first().json.response || '').trim();
const topic = $('Build Prompt').first().json.topic;

function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

function renderInline(text){
  let t = esc(text);
  t = t.replace(/\[(\d+)\]/g, '<sup class="cite">[$1]</sup>');
  t = t.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  t = t.replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2">$1</a>');
  t = t.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1">$1</a>');
  return t;
}

const lines = md.split(/\r?\n/);
let html = '';
let inList = false;
function closeList(){ if(inList){ html += '</ul>'; inList = false; } }
for (const raw of lines){
  const line = raw.trimEnd();
  if (!line.trim()){ closeList(); continue; }
  let m;
  if ((m = line.match(/^#\s+(.*)/))){ closeList(); html += '<h1>' + renderInline(m[1]) + '</h1>'; }
  else if ((m = line.match(/^##\s+(.*)/))){ closeList(); html += '<h2>' + renderInline(m[1]) + '</h2>'; }
  else if ((m = line.match(/^###\s+(.*)/))){ closeList(); html += '<h3>' + renderInline(m[1]) + '</h3>'; }
  else if ((m = line.match(/^[-*]\s+(.*)/))){ if(!inList){ html += '<ul>'; inList = true; } html += '<li>' + renderInline(m[1]) + '</li>'; }
  else if ((m = line.match(/^\d+\.\s+(.*)/))){ if(!inList){ html += '<ul>'; inList = true; } html += '<li>' + renderInline(m[1]) + '</li>'; }
  else { closeList(); html += '<p>' + renderInline(line) + '</p>'; }
}
closeList();

const now = new Date().toISOString().slice(0,10);
const doc = `<!DOCTYPE html>\n<html lang="en"><head><meta charset="utf-8"><title>Research Brief: ${esc(topic)}</title>\n<style>\n@page { margin: 28mm 20mm; }\nbody { font-family: -apple-system, 'Segoe UI', Helvetica, Arial, sans-serif; color: #1a1a1a; line-height: 1.55; font-size: 12pt; }\n.header { border-bottom: 3px solid #2b6cb0; padding-bottom: 10px; margin-bottom: 24px; }\n.header .kicker { color: #2b6cb0; font-size: 10pt; letter-spacing: 1.5px; text-transform: uppercase; font-weight: 600; }\n.header .date { color: #718096; font-size: 10pt; margin-top: 4px; }\nh1 { font-size: 20pt; color: #1a202c; margin: 0 0 6px; }\nh2 { font-size: 14pt; color: #2b6cb0; margin: 22px 0 8px; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; }\nh3 { font-size: 12pt; color: #2d3748; margin: 16px 0 6px; }\np { margin: 8px 0; }\nul { margin: 8px 0 8px 4px; padding-left: 22px; }\nli { margin: 5px 0; }\nsup.cite { color: #2b6cb0; font-weight: 600; }\na { color: #2b6cb0; word-break: break-all; }\n.footer { margin-top: 32px; padding-top: 10px; border-top: 1px solid #e2e8f0; color: #a0aec0; font-size: 9pt; }\n</style></head>\n<body>\n<div class="header"><div class="kicker">Research Brief - by Mira</div><div class="date">${now}</div></div>\n${html}\n<div class="footer">Generated locally via Ollama (qwen3:8b) + SearXNG. Verify sources before relying on figures.</div>\n</body></html>`;

return [{ json: { html: doc, topic } }];
